# ---- server ----------------------------------------------------------------------------------------------------
server <- function(input, output, session) {
  observeEvent(input$home_aov, updateNavbarPage(session, "nav", selected = "Analysis of variance"))
  observeEvent(input$home_tt, updateNavbarPage(session, "nav", selected = "t-test"))
  observeEvent(input$home_corr, updateNavbarPage(session, "nav", selected = "Correlation"))
  observeEvent(input$home_reg, updateNavbarPage(session, "nav", selected = "Regression"))
  # ---- plot style shared by every plot ----
  for (k in names(style_defaults)) for (s in style_screens) local({
    k <- k; s <- s; id <- paste0(s, "_", k)
    observeEvent(input[[id]], for (o in setdiff(style_screens, s)) {
      oid <- paste0(o, "_", k)
      if (!identical(input[[oid]], input[[id]])) updateSelectInput(session, oid, selected = input[[id]])
    }, ignoreInit = TRUE)
  })
  plot_style <- function(p) {
    get <- function(k) input[[paste0(p, "_", k)]] %||% style_defaults[[k]]
    list(palette = get("pal"), theme = get("theme"), base_size = as.numeric(get("size")), legend = get("legend"))
  }
  # width and height in inches of a downloaded plot
  export_dims <- function(p) {
    d <- input[[paste0(p, "_dim")]] %||% "std"
    cm <- suppressWarnings(as.numeric(if (d == "custom") c(input[[paste0(p, "_w")]], input[[paste0(p, "_h")]]) else export_sizes[[d]]))
    if (length(cm) != 2 || anyNA(cm)) cm <- export_sizes$std
    pmin(pmax(cm, 3), 60) / 2.54
  }
  gg_version <- function() tryCatch(as.character(utils::packageVersion("ggplot2")), error = function(e) "")
  output$methods_text <- renderUI({
    sentence <- methods_sentence(gg_version())
    tagList(
      div(class = "well well-sm", sentence), actionButton("cp_methods", "คัดลอกประโยค"),
      h4("เอกสารอ้างอิงของซอฟต์แวร์"), tags$ul(lapply(package_refs(), tags$li)), actionButton("cp_refs", "คัดลอกเอกสารอ้างอิง"),
      h4("ผลแต่ละส่วนคำนวณจากอะไร"),
      html_table(data.frame(`ผลลัพธ์` = c("ตาราง ANOVA (CRD, RCBD, split plot)", "อักษรเปรียบเทียบค่าเฉลี่ย", "การทดสอบที (t-test)", "การวิเคราะห์ร่วมหลายสถานที่ และ Bartlett's test", "การทดสอบแบบไม่อิงพารามิเตอร์", "SE(m), SED, LSD", "สหสัมพันธ์และค่า p", "การถดถอย ตาราง ANOVA และสัมประสิทธิ์", "การตรวจสอบการแจกแจงปกติ ความแปรปรวน และค่าผิดปกติ", "กราฟ"),
                            `คำนวณโดย` = c("R stats::aov", "agricolae (LSD.test, HSD.test, duncan.test)", "R stats::t.test, stats::var.test, stats::shapiro.test", "R stats::aov, Bartlett's test computed from the error mean squares", "agricolae (kruskal, friedman), R stats::wilcox.test", "error mean square and df from the ANOVA, stats::qt", "R stats::cor.test", "R stats::lm", "R stats::shapiro.test, nortest::lillie.test, lmtest::bptest, studentized residuals from stats", "ggplot2 and R graphics"), check.names = FALSE, stringsAsFactors = FALSE)),
      p(class = "text-muted", sprintf("รุ่นที่ใช้ในการใช้งานครั้งนี้: %s, ggplot2 %s",R.version.string, gg_version())))
  })
  observeEvent(input$cp_refs, session$sendCustomMessage("copy_text", list(what = "References", text = paste(package_refs(), collapse = "\n\n"))))
observeEvent(input$cp_mrefs, session$sendCustomMessage("copy_text", list(what = "Method references", text = paste(method_refs, collapse = "

"))))
  observeEvent(input$cp_methods, session$sendCustomMessage("copy_text", list(what = "Methods sentence", text = methods_sentence(gg_version()))))
  # TRUE when the controls (as summarised by sig()) differ from what they were when the button was last pressed
  stale_flag <- function(button, sig) {
    ran <- reactiveVal(NULL)
    observeEvent(input[[button]], ran(sig()))
    stale <- reactive(!is.null(ran()) && !identical(ran(), sig()))
    # grey out and lock that screen's results (see stale_js); its outputs are inside <screen>_out
    observe(session$sendCustomMessage("stale", list(id = paste0(sub("^go_", "", button), "_out"), on = stale())))
    stale
  }
  # explicit cache: the default application cache is not set up when the app runs in the browser (webR)
  star_cache <- cachem::cache_mem(max_size = 100 * 1024^2)
  output$example_picker <- renderUI(selectInput("example", "Example", examples[[input$design]]))
  setup <- reactive(if (input$src == "ex" && !is.null(input$example) && input$example %in% names(example_setup)) example_setup[[input$example]])

  output$template_label <- renderText({
    switch(input$design %||% "CRD",
           CRD = "CRD",
           RCBD = "RCBD",
           SplitCRD = "Split-plot CRD",
           SplitRCBD = "Split-plot RCBD",
           CombRCBD = "RCBD over sites",
           CombCRD = "CRD over sites",
           "CRD")
  })
  output$dl_template <- downloadHandler(
    filename = function() sprintf("rdstat_template_%s.xlsx", tolower(input$design %||% "crd")),
    content = function(file) {
      des <- input$design %||% "CRD"
      tbl <- switch(des,
        CRD = data.frame(
          Treatment = rep(c("Variety_A", "Variety_B", "Variety_C", "Variety_D"), each = 4),
          Replication = rep(1:4, times = 4),
          Yield = rep(NA_real_, 16),
          stringsAsFactors = FALSE
        ),
        RCBD = data.frame(
          Block = rep(1:4, times = 4),
          Treatment = rep(c("Variety_A", "Variety_B", "Variety_C", "Variety_D"), each = 4),
          Yield = rep(NA_real_, 16),
          stringsAsFactors = FALSE
        ),
        SplitCRD = data.frame(
          MainPlot = rep(c("Main_A", "Main_B"), each = 12),
          Replication = rep(rep(1:4, each = 3), times = 2),
          SubPlot = rep(c("Sub_1", "Sub_2", "Sub_3"), times = 8),
          Yield = rep(NA_real_, 24),
          stringsAsFactors = FALSE
        ),
        SplitRCBD = data.frame(
          Block = rep(1:4, each = 6),
          MainPlot = rep(rep(c("Main_A", "Main_B"), each = 3), times = 4),
          SubPlot = rep(c("Sub_1", "Sub_2", "Sub_3"), times = 8),
          Yield = rep(NA_real_, 24),
          stringsAsFactors = FALSE
        ),
        CombRCBD = data.frame(
          Site = rep(c("Site_1", "Site_2", "Site_3"), each = 16),
          Block = rep(rep(1:4, each = 4), times = 3),
          Treatment = rep(c("Variety_A", "Variety_B", "Variety_C", "Variety_D"), times = 12),
          Yield = rep(NA_real_, 48),
          stringsAsFactors = FALSE
        ),
        CombCRD = data.frame(
          Site = rep(c("Site_1", "Site_2", "Site_3"), each = 16),
          Treatment = rep(rep(c("Variety_A", "Variety_B", "Variety_C", "Variety_D"), each = 4), times = 3),
          Replication = rep(1:4, times = 12),
          Yield = rep(NA_real_, 48),
          stringsAsFactors = FALSE
        )
      )
      writexl::write_xlsx(list(Template = tbl), file)
    }
  )

  raw_dat <- reactive({
    if (input$src == "ex") { s <- setup(); req(s); return(read.csv(s$file)) }
    req(input$file)
    # every column is read as text so that the engine can check and convert it (decimal commas, units, "n/a", ...)
    tryCatch(star_read_table(input$file$datapath, input$file$name),
             error = function(e) { showNotification(paste("Could not read the file:", conditionMessage(e)), type = "error"); req(FALSE) })
  })
  # a wide-format upload (one column per replication) is analysed only after the user agrees to convert it to long format
  to_long <- reactiveVal(FALSE)
  observeEvent(input$file, to_long(FALSE))
  observeEvent(input$wide_convert, to_long(TRUE))
  observeEvent(input$wide_undo, to_long(FALSE))
  wide_cols <- reactive(if (input$src == "up") wide_rep_cols(raw_dat()) else character())
  dat <- reactive(if (to_long() && length(wide_cols())) wide_to_long(raw_dat(), wide_cols()) else raw_dat())
  output$wide_note <- renderUI({
    cols <- wide_cols(); if (!length(cols)) return(NULL)
    if (to_long()) return(div(class = "alert alert-success small", icon("circle-check"), " ",
      sprintf("Converted to long format: %d rows, with the replication in column Rep and the values in column Value (see the Data tab).", nrow(dat())),
      actionLink("wide_undo", "Undo")))
    div(class = "alert alert-warning small", icon("triangle-exclamation"), " ", strong("This file looks like wide format: "),
        sprintf("the columns %s each hold one replication. The analysis needs one row per plot (long format).", paste(cols, collapse = ", ")),
        div(class = "mt-2", actionButton("wide_convert", "Convert to long format", class = "btn-warning btn-sm")))
  })
  output$data_ui <- renderUI(data_preview_ui(dat()))
  output$var_pickers <- renderUI({
    d <- dat(); nm <- names(d); s <- setup()
    num <- numeric_cols(d)
    resp_choices <- if (length(num)) num else nm
    resp_sel <- if (!is.null(s) && s$resp %in% resp_choices) s$resp else tail(resp_choices, 1)
    tagList(
      selectInput("resp", "Response variable (numeric)", resp_choices, selected = resp_sel),
      if (is_split(input$design)) tagList(
        selectInput("trt_main", "Main-plot factor", nm, selected = if (!is.null(s)) s$trt[1] else nm[min(2, length(nm))]),
        selectInput("trt_sub", "Sub-plot factor", nm, selected = if (!is.null(s)) s$trt[2] else nm[min(3, length(nm))]))
      else if (is_comb(input$design)) tagList(
        selectInput("trt", "Treatment factor (one)", nm, selected = if (!is.null(s)) s$trt else nm[min(2, length(nm))]),
        selectInput("env", "Environment: site, season or year", nm, selected = if (!is.null(s)) s$env else nm[1]))
      else selectizeInput("trt", "Treatment factor(s): one or two", nm, multiple = TRUE,
                     selected = if (!is.null(s)) s$trt else nm[min(2, length(nm))], options = list(maxItems = 2)),
      if (input$design == "CombRCBD") tagList(selectInput("blk", "Block / replication within each environment", nm, selected = if (!is.null(s)) s$blk else nm[1]),
                                              helpText("Blocks are numbered within each environment (block 1 at one site is not block 1 at another); the analysis nests them in the environment.")),
      if (input$design == "SplitCRD") tagList(selectInput("blk", "Replication: main-plot number within each main-plot level", nm, selected = if (!is.null(s)) s$blk else nm[1]),
                                              helpText("1, 2, 3, ... for the main plots of each level of the main-plot factor. Not a block: in CRD the main plots are not grouped.")),
      if (input$design == "RCBD") selectInput("blk", "Block / replication", nm, selected = if (!is.null(s)) s$blk else nm[1]),
      if (input$design == "SplitRCBD") tagList(selectInput("blk", "Block: group of main plots holding every main-plot level", nm, selected = if (!is.null(s)) s$blk else nm[1]),
                                               helpText("The block (replication) each main plot is in, not a number of the main plot itself.")),
      if (is_split(input$design)) tagList(uiOutput("split_check"),
        help_box("Block or main-plot number?",
          p(strong("Block (Split plot in RCBD):"), " the field was divided into blocks and each block holds one main plot of every main-plot level. The block column repeats 1, 2, 3 ... across the main-plot levels."),
          p(strong("Main-plot number (Split plot in CRD):"), " there are no blocks; the main plots of each level are simply numbered 1, 2, 3 ..."),
          p("The two give different degrees of freedom for Error(a), which tests the main-plot factor, so choose the design that matches how the field was laid out. The check above shows the df that your choice gives.")))
    )
  })
  observeEvent(input$resp, {
    req(input$resp, dat())
    if (!is_split(input$design %||% "CRD")) {
      cur_trt <- isolate(input$trt)
      if (input$resp %in% cur_trt) {
        updateSelectizeInput(session, "trt", selected = setdiff(cur_trt, input$resp))
      }
    }
  }, ignoreInit = TRUE)
  output$split_check <- renderUI({
    req(is_split(input$design), input$trt_main, input$trt_sub, input$blk)
    d <- dat(); req(all(c(input$trt_main, input$trt_sub, input$blk) %in% names(d)))
    split_layout_check(d, input$design, input$trt_main, input$trt_sub, input$blk)
  })

  # Runs on "Run ANOVA" only. Results are cached by data and settings, so going back to an earlier choice
  # (e.g. LSD -> Tukey -> LSD) reuses the earlier result instead of analysing again. The classic STAR report is
  # built later, only when it is viewed, copied or downloaded (see report_text).
  res <- reactive({
    req(input$resp)
    blk <- if (needs_block(input$design)) { req(input$blk); input$blk } else NULL
    if (is_split(input$design)) req(input$trt_main, input$trt_sub) else req(input$trt)
    if (is_comb(input$design)) req(input$env)
    tr <- input$transform %||% "none"
    tryCatch({
      td <- transform_response(dat(), input$resp, tr)
      r <- if (is_split(input$design)) star_splitplot(td$data, td$resp, input$trt_main, input$trt_sub, blk, test = input$pw,
                                                      alpha = as.numeric(input$alpha), report = FALSE, design = input$design)
           else if (is_comb(input$design)) star_combined(td$data, td$resp, input$trt, input$env, blk, design = sub("^Comb", "", input$design),
                                                         test = input$pw, alpha = as.numeric(input$alpha), report = FALSE)
           else star_aov(td$data, td$resp, input$trt, blk, design = input$design, test = input$pw,
                         alpha = as.numeric(input$alpha), report = FALSE)
      if (tr != "none") { r$transform <- tr; r$original_response <- input$resp }
      r
    }, error = function(e) structure(list(message = conditionMessage(e)), class = "star_error"))
  }) |>
    bindCache(dat(), input$design, input$resp, input$transform, input$trt, input$env, input$trt_main, input$trt_sub, input$blk, input$pw, input$alpha, cache = star_cache) |>
    bindEvent(input$go_aov)
  ok <- reactive({ r <- res(); req(!inherits(r, "star_error")); r })
  # rank-based alternative for one treatment factor in a CRD (Kruskal-Wallis) or an RCBD (Friedman); NULL otherwise
  np_res <- reactive({
    r <- ok()
    if (!r$design %in% c("CRD", "RCBD") || length(r$factors) != 1) return(NULL)
    tryCatch(star_nonparametric(r$data, r$response, r$factors, r$block, r$alpha), error = function(e) NULL)
  })
  np_display <- function(np) {
    m <- np$means
    out <- data.frame(m$Treatment, fmt_n(m$Median), formatC(m$N, format = "d"), fmt_n(m$Rank), stringsAsFactors = FALSE)
    names(out) <- c(np$treatment, "Median", "N", np$rank_label)
    if (np$significant) out$Group <- m$Group
    out
  }
  np_ui <- function(np) tagList(
    p(np$summary),
    html_table(np_display(np)),
    p(class = "text-muted small mb-0", if (np$significant) sprintf("Treatments with the same letter do not differ (comparison of %s, agricolae). ", tolower(np$rank_label)) else "",
      "The rank-based test does not assume normal residuals or equal variances; use it when the checks above fail and a transformation does not help."))
  # The data behind the current results (for plotting observations). Stored when Run is pressed: an eventReactive would
  # only read the data when first asked for, by which time the user may have switched to another example.
  used_data <- reactiveVal(NULL)
  # with a transformation the plotted observations must be on the transformed scale, like the means
  observeEvent(input$go_aov, used_data(tryCatch(transform_response(dat(), input$resp, input$transform)$data, error = function(e) dat())))
  aov_sig <- reactive(list(input$design, input$src, input$example, input$file$name, to_long(), input$resp, input$transform, input$trt, input$env, input$trt_main, input$trt_sub,
                           input$blk, input$pw, input$alpha))
  aov_stale <- stale_flag("go_aov", aov_sig)
  output$aov_msg <- renderUI({
    if (!isTRUE(input$go_aov > 0)) return(run_hint("Run ANOVA"))
    r <- res()
    tagList(if (aov_stale()) stale_note("go_aov"), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })

  # tables prepared once so that the screen, the clipboard and the Excel file agree
  tables <- reactive({
    r <- ok(); fs <- r$factors
    out <- list(anova = anova_display(r$anova), means = list(), letters = list(), cells = NULL, simple = list(), agronomy = list())
    for (f in fs) {
      show <- isTRUE(r$effects$Significant[r$effects$Effect == f]) && !r$interaction_significant
      out$letters[[f]] <- show
      m_df <- means_display(r$means[[f]], f, show, back = if (!is.null(r$transform)) transforms[[r$transform]]$back)
      out$means[[f]] <- m_df
      out$agronomy[[f]] <- agronomy_display(r, f, m_df)
    }
    if (!is.null(r$cells)) out$cells <- cells_display(r$cells, fs[1], fs[2])
    for (nm in names(r$simple)) out$simple[[nm]] <- simple_display(r$simple[[nm]])
    out
  })

  output$results_ui <- renderUI({
    r <- ok(); tb <- tables()
    sig <- r$effects$Effect[r$effects$Significant %in% TRUE]
    # with a significant interaction the overall means are not compared, so the highest cell mean is shown instead
    top_stat <- if (isTRUE(r$interaction_significant) && !is.null(r$cells)) {
      cl <- r$cells[which.max(r$cells$Mean), ]
      stat("Highest cell mean", fmt_n(cl$Mean), paste(r$factors, "=", c(cl[[r$factors[1]]], cl[[r$factors[2]]]), collapse = ", "))
    } else {
      top_f <- if (length(intersect(sig, r$factors))) intersect(sig, r$factors)[1] else r$factors[1]
      top <- r$means[[top_f]][which.max(r$means[[top_f]]$Mean), ]
      stat(paste("Highest mean of", top_f), fmt_n(top$Mean), top$Treatment)
    }
    tagList(
      notes_ui(r$data_notes),
      div(class = if (r$significant || r$interaction_significant) "alert alert-success" else "alert alert-info", r$summary),
      key_stats(
        stat("Significant effects", sprintf("%d of %d", length(sig), nrow(r$effects)), if (length(sig)) paste(sig, collapse = ", ") else "none"),
        stat("Grand mean", fmt_n(r$grand_mean), r$original_response %||% r$response),
        stat("CV", if (is.null(r$cv_a)) sprintf("%.1f%%", r$cv) else sprintf("%.1f%% / %.1f%%", r$cv_a, r$cv_b), if (!is.null(r$cv_a)) "Error (a) / Error (b)"),
        top_stat),
      result_card("สรุปผล (ภาษาไทย)", p(lang = "th", thai_summary_aov(r)), copy = "cp_aov_th", copy_label = "คัดลอก"),
      result_card("Analysis of variance", html_table(tb$anova), copy = "cp_anova", copy_label = "Copy table",
                  if (is_comb(r$design)) p(class = "text-muted small mb-0", sprintf("Environments are fixed effects, as in STAR: %s is tested against %s; the other effects against the pooled error.",
                                                                                  r$env, if (identical(r$design, "CombRCBD")) paste(r$block, "within", r$env) else "the pooled error"))),
      if (is_comb(r$design)) result_card(paste("Analysis of each", r$env), html_table(by_env_display(r)), bartlett_note(r)),
      result_card("Means (publication layout)", copy = "cp_means", copy_label = "Copy means tables",
        if (!is.null(r$transform)) p(class = "text-muted small", icon("circle-info"), sprintf(" The analysis used %s transformed as %s. Means, SE, letters, SE(m), SED and LSD are on the transformed scale; the original-unit column gives the means back-transformed for reporting.",
                                                                                              r$original_response, transforms[[r$transform]]$label)),
        lapply(names(tb$agronomy), function(f) tagList(h6(paste("Means of", f)), html_table(tb$agronomy[[f]]),
                                                     if (tb$letters[[f]]) p(class = "text-muted small", "Means with the same letter are not significantly different.") else no_letters_note(r, f))),
        p(class = "text-muted small", agronomy_note(r)),
        if (!is.null(tb$cells)) tagList(h6(paste("Cell means:", paste(r$factors, collapse = " x "))), html_table(tb$cells))),
      lapply(names(tb$simple), function(nm) {
        sm <- r$simple[[nm]]
        result_card(sprintf("Comparison of %s at each level of %s (%s test)", attr(sm, "compare"), attr(sm, "at"), attr(sm, "test")),
                    html_table(tb$simple[[nm]]),
                    p(class = "text-muted small mb-0", "Means with the same letter (within a column) are not significantly different."))
      }),
      result_card("APA-style report", lapply(r$apa, p), copy = "cp_apa")
    )
  })

  output$plot_picker <- renderUI({
    r <- ok()
    ch <- c(setNames(r$factors, paste("Means of", r$factors)), if (!is.null(r$cells)) c("Interaction (grouped bars)" = "interaction", if (use_gg()) c("Interaction (lines)" = "interaction_line")))
    cur <- isolate(input$plot_effect)   # keep the choice when the style is switched
    if (length(ch) > 1) selectInput("plot_effect", "Plot", ch, selected = if (!is.null(cur) && cur %in% ch) cur else if (r$interaction_significant) "interaction" else r$factors[1])
  })
  plot_effect <- reactive({ r <- ok(); pe <- input$plot_effect; if (is.null(pe) || !(pe %in% c(r$factors, if (!is.null(r$cells)) c("interaction", "interaction_line")))) r$factors[1] else pe })
  use_gg <- reactive(identical(input$plot_style, "gg"))
  # the ggplot2 figure (a ggplot object); the classic style is drawn with base graphics instead
  gg_means <- reactive(do.call(star_ggplot_means, c(list(ok(), plot_effect(), data = if (isTRUE(input$gg_points)) used_data(), error = input$gg_error %||% "se",
                                                         main = input$gg_title, xlab = input$gg_xlab, ylab = input$gg_ylab), plot_style("aov"))))
  draw_means <- function() {
    if (use_gg()) print(gg_means())
    else star_plot_means(ok(), sub("_line$", "", plot_effect()), main = input$gg_title, xlab = input$gg_xlab, ylab = input$gg_ylab)
  }
  output$means_plot <- renderPlot(draw_means())
  output$diag_ui <- renderUI({
    dg <- ok()$diagnostics
    if (is.null(dg)) return(div(class = "alert alert-warning", if (is_split(ok()$design)) "Assumption checks are not available for split-plot designs yet." else "Assumption checks could not be computed for this data."))
    tagList(
      diag_summary_cards(dg),
      div(class = if (dg$ok) "alert alert-success" else "alert alert-warning", tags$ul(lapply(dg$messages, tags$li))),
      if (nrow(dg$outliers)) {
        o <- dg$outliers
        o[] <- lapply(o, function(v) if (is.numeric(v)) fmt_n(v, 3) else as.character(v))
        tagList(h4("Flagged observations"), p(class = "text-muted", "Row = row number in your data. |Studentized residual| > 3 = outlier, 2 to 3 = suspect."), html_table(o))
      },
      if (!is.null(np <- np_res())) result_card(paste("Rank-based alternative:", np$name, "test"), np_ui(np), copy = "cp_np", copy_label = "Copy table"))
  })
  observeEvent(input$cp_np, session$sendCustomMessage("copy_text", list(what = "Rank-based test", text = paste(np_res()$summary, tsv(np_display(np_res())), sep = "\n"))))
  gg_diag <- function(dg, p) { st <- plot_style(p); star_ggplot_diagnostics(dg, st$base_size - 1, st$theme, st$legend) }
  output$diag_plot <- renderPlot({ dg <- ok()$diagnostics; req(dg); if (identical(input$diag_style, "gg")) print(gg_diag(dg, "aov")) else star_plot_diagnostics(dg) })
  report_text <- reactive(star_report(ok())) |> bindCache(ok(), cache = star_cache)
  output$report <- renderText(paste(report_text(), collapse = "\n"))

  xlsx_sheets <- reactive({
    r <- ok(); tb <- tables()
    sheets <- list(ANOVA = r$anova,
                   # the factors' tables differ in their first column name and in having a Group column
                   `Publication table` = do.call(rbind, lapply(names(tb$agronomy), function(f) {
                     a <- tb$agronomy[[f]]; names(a)[1] <- "Level"
                     if (!"Group" %in% names(a)) a$Group <- ""
                     data.frame(Effect = f, a, check.names = FALSE, stringsAsFactors = FALSE)
                   })),
                   Means = do.call(rbind, lapply(names(tb$means), function(f) {
                     m <- data.frame(Effect = f, r$means[[f]], row.names = NULL)
                     if (!tb$letters[[f]]) m$Group <- ""   # as on the screen: no letters without a significant F test
                     if (!is.null(r$transform)) m$`Mean (original unit)` <- transforms[[r$transform]]$back(m$Mean)
                     pr <- precision_of(r, f); m$`SE(m)` <- pr[["sem"]]; m$SED <- pr[["sed"]]; m$LSD <- pr[["lsd"]]
                     m
                   })))
    if (is_comb(r$design)) sheets$`Each environment` <- cbind(r$by_env, `Bartlett p (all environments)` = c(r$bartlett$p, rep(NA, nrow(r$by_env) - 1)))
    if (!is.null(r$cells)) sheets$`Cell means` <- r$cells
    if (length(r$simple)) sheets$`Simple effects` <- do.call(rbind, lapply(names(r$simple), function(nm) {
      sm <- r$simple[[nm]]; data.frame(Comparison = nm, setNames(sm[c(attr(sm, "at"), attr(sm, "compare"), "Mean", "N", "SE", "Group")], c("At level", "Level", "Mean", "N", "SE", "Group")), row.names = NULL)
    }))
    sheets$Info <- data.frame(Item = c("App version", "Design", "Response", "Transformation", "Treatment factor(s)", "Block", "Mean comparison", "Alpha", "Grand mean", "CV (%)", "Summary", "Data checks"),
                              Value = c(version_label(), r$design, r$response, if (is.null(r$transform)) "none" else paste(transforms[[r$transform]]$label, "of", r$original_response), paste(r$factors, collapse = ", "), if (is.null(r$block)) "-" else r$block,
                                        if (r$test == "auto") "auto (LSD if <= 5 levels, else HSD)" else r$test, r$alpha,
                                        round(r$grand_mean, 4),
                                        if (is.null(r$cv_a)) round(r$cv, 2) else sprintf("CV(a) = %.2f, CV(b) = %.2f", r$cv_a, r$cv_b), r$summary,
                                        if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none"))
    sheets
  })
  output$dl_xlsx <- downloadHandler("rdstat_anova.xlsx", function(file) writexl::write_xlsx(xlsx_sheets(), file))
  output$dl_aov_plot <- downloadHandler(function() paste0("rdstat_means_plot.", input$aov_fmt), function(file) {
    fmt <- input$aov_fmt %||% "png"; dpi <- as.numeric(input$aov_dpi %||% 300); wh <- export_dims("aov")
    if (use_gg()) { star_ggsave(gg_means(), file, width = wh[1], height = wh[2], dpi = dpi); return(invisible()) }
    if (fmt == "png") png(file, width = wh[1] * dpi, height = wh[2] * dpi, res = dpi)
    else if (fmt == "svg") svg(file, width = wh[1], height = wh[2]) else pdf(file, width = wh[1], height = wh[2])
    on.exit(dev.off()); draw_means()
  })
  output$dl_txt <- downloadHandler("rdstat_anova_report.txt", function(file) writeLines(c(paste(app_name, "web app", version_label()), "", report_text()), file))

  # ---- Thai summary and Word report ----
  aov_file_name <- reactive(if (input$src == "up") input$file$name else setup()$file)
  observeEvent(input$cp_aov_th, session$sendCustomMessage("copy_text", list(what = "สรุปผล", text = thai_summary_aov(ok()))))
  design_names <- c(CRD = "Completely randomized design (CRD)", RCBD = "Randomized complete block design (RCBD)",
                    SplitCRD = "Split plot in CRD", SplitRCBD = "Split plot in RCBD",
                    CombRCBD = "Combined analysis over environments (RCBD)", CombCRD = "Combined analysis over environments (CRD)")
  output$dl_doc <- downloadHandler("rdstat_anova_report.doc", function(file) {
    r <- ok(); tb <- tables(); np <- np_res(); dg <- r$diagnostics
    png <- tryCatch({ f <- tempfile(fileext = ".png"); star_ggsave(gg_means(), f, width = 6.5, height = 4.5, dpi = 200); f }, error = function(e) NULL)
    info <- data.frame(Item = c("Design", "Response", "Treatment factor(s)", "Block", "Transformation", "Mean comparison", "Alpha", "Data", "Date", "App"),
                       Value = c(design_names[[r$design]], r$original_response %||% r$response, paste(r$factors, collapse = ", "), r$block %||% "-",
                                 if (is.null(r$transform)) "none" else transforms[[r$transform]]$label, paste(unique(r$tests_used), collapse = ", "),
                                 r$alpha, aov_file_name() %||% "-", format(Sys.Date()), paste(app_name, version_label())), stringsAsFactors = FALSE)
    blocks <- c(word_table(info),
      w_h2("สรุปผล"), w_p(thai_summary_aov(r)), w_p(r$summary),
      w_h2("Analysis of variance"), word_table(tb$anova),
      if (is_comb(r$design)) c(w_h2(paste("Analysis of each", r$env)), word_table(by_env_display(r)), w_p(.star_bartlett_text(r$bartlett, r$alpha), "small")),
      w_h2("Means"), unlist(lapply(names(tb$agronomy), function(f) c(w_p(paste("Means of", f)), word_table(tb$agronomy[[f]])))),
      w_p(paste("Means with the same letter are not significantly different.", agronomy_note(r)), "small"),
      if (!is.null(tb$cells)) c(w_p(paste("Cell means:", paste(r$factors, collapse = " x "))), word_table(tb$cells)),
      unlist(lapply(names(tb$simple), function(nm) c(w_p(nm), word_table(tb$simple[[nm]])))),
      if (!is.null(dg)) c(w_h2("Assumption checks"), paste0("<ul>", paste0("<li>", htmltools::htmlEscape(dg$messages), "</li>", collapse = ""), "</ul>")),
      if (!is.null(np)) c(w_h2(paste("Rank-based alternative:", np$name)), w_p(np$summary), word_table(np_display(np))),
      w_h2("APA-style report"), vapply(r$apa, w_p, ""),
      w_h2("Methods and references"), w_p(methods_sentence(gg_version())), paste0("<ul>", paste0("<li>", htmltools::htmlEscape(package_refs()), "</li>", collapse = ""), "</ul>"))
    word_doc(file, paste(app_name, "- analysis of variance:", r$original_response %||% r$response), blocks, png)
  })

  observeEvent(input$cp_anova, session$sendCustomMessage("copy_text", list(what = "ANOVA table", text = tsv(tables()$anova))))
  observeEvent(input$cp_means, session$sendCustomMessage("copy_text", list(what = "Means tables", text = paste(
    c(unlist(lapply(names(tables()$agronomy), function(f) c(paste("Means of", f), tsv(tables()$agronomy[[f]]), ""))), agronomy_note(ok()), "",
      if (!is.null(tables()$cells)) c("Cell means", tsv(tables()$cells), ""),
      unlist(lapply(names(tables()$simple), function(nm) c(nm, tsv(tables()$simple[[nm]]), "")))), collapse = "\n"))))
  observeEvent(input$cp_apa, session$sendCustomMessage("copy_text", list(what = "APA text", text = paste(ok()$apa, collapse = " "))))
  observeEvent(input$cp_report, session$sendCustomMessage("copy_text", list(what = "Report", text = paste(report_text(), collapse = "\n"))))
  observeEvent(input$copy_status, {
    st <- input$copy_status
    showNotification(if (isTRUE(st$ok)) paste(st$what, "copied to clipboard") else "Copy failed: select the text and copy manually",
                     type = if (isTRUE(st$ok)) "message" else "error", duration = 3)
  })

  # ---- shared by the correlation and regression screens ----
  use_data <- function(p, setups) reactive({
    if (input[[paste0(p, "_src")]] == "ex") { s <- setups[[input[[paste0(p, "_example")]]]]; req(s); return(read.csv(s$file)) }
    f <- input[[paste0(p, "_file")]]; req(f)
    tryCatch(star_read_table(f$datapath, f$name),
             error = function(e) { showNotification(paste("Could not read the file:", conditionMessage(e)), type = "error"); req(FALSE) })
  })
  example_of <- function(p, setups) if (input[[paste0(p, "_src")]] == "ex") setups[[input[[paste0(p, "_example")]]]]
  as_error <- function(e) structure(list(message = conditionMessage(e)), class = "star_error")
  plot_download <- function(p, plot_fn) downloadHandler(
    function() paste0("rdstat_", p, "_plot.", input[[paste0(p, "_fmt")]] %||% "png"),
    function(file) { wh <- export_dims(p); star_ggsave(plot_fn(), file, width = wh[1], height = wh[2], dpi = as.numeric(input[[paste0(p, "_dpi")]] %||% 300)) })
  notes_ui <- function(notes) if (length(notes)) div(class = "alert alert-warning", strong("Data checks"), tags$ul(lapply(notes, tags$li)))
  copy_button <- function(id, what, text) observeEvent(input[[id]], session$sendCustomMessage("copy_text", list(what = what, text = text())))

  # ---- t-test ----
  tt_dat <- use_data("tt", tt_setup)
  output$tt_data_ui <- renderUI(data_preview_ui(tt_dat()))
  observeEvent(input$tt_example, { s <- tt_setup[[input$tt_example]]; if (!is.null(s) && input$tt_src == "ex") updateRadioButtons(session, "tt_type", selected = s$type) })
  output$tt_pickers <- renderUI({
    d <- tt_dat(); nm <- names(d); num <- numeric_cols(d); s <- example_of("tt", tt_setup)
    if (!is.null(s) && !identical(s$type, input$tt_type)) s <- NULL   # the example is for another kind of test
    switch(input$tt_type,
      independent = {
        resp <- if (!is.null(s)) s$resp else tail(num, 1)
        tagList(selectInput("tt_resp", "Response (numeric)", num, selected = resp),
                selectInput("tt_group", "Group column", setdiff(nm, resp), selected = if (!is.null(s)) s$group else setdiff(nm, num)[1]),
                uiOutput("tt_level_picker"))
      },
      paired = tagList(
        selectInput("tt_x", "First measurement", num, selected = if (!is.null(s)) s$x else num[1]),
        selectInput("tt_y", "Second measurement", num, selected = if (!is.null(s)) s$y else num[min(2, length(num))]),
        helpText("One row per unit; the test is on the differences first - second.")),
      one = tagList(
        selectInput("tt_resp", "Variable (numeric)", num, selected = if (!is.null(s)) s$resp else tail(num, 1)),
        numericInput("tt_mu", "Test value (the mean is compared with this)", if (!is.null(s)) s$mu else 0)))
  })
  output$tt_level_picker <- renderUI({
    req(input$tt_group, input$tt_group %in% names(tt_dat()))
    g <- tt_dat()[[input$tt_group]]
    lv <- star_level_order(unique(star_squash_space(as.character(g[!star_is_blank(g)]))))
    s <- example_of("tt", tt_setup)
    sel <- if (!is.null(s) && identical(s$group, input$tt_group) && !is.null(s$levels)) s$levels else head(lv, 2)
    tagList(selectizeInput("tt_levels", "Groups to compare (first, second)", lv, selected = sel, multiple = TRUE, options = list(maxItems = 2)),
            if (length(lv) > 2) helpText(sprintf("This column has %d groups; the t-test compares two. For all of them use Analysis of variance.", length(lv))))
  })
  observeEvent(input$tt_resp, {   # the response cannot also be the group column
    if (identical(input$tt_type, "independent") && identical(input$tt_group, input$tt_resp))
      updateSelectInput(session, "tt_group", selected = setdiff(names(tt_dat()), input$tt_resp)[1])
  }, ignoreInit = TRUE)
  tt_res <- reactive({
    alpha <- as.numeric(input$tt_alpha); d <- tt_dat()
    tryCatch(switch(input$tt_type,
      independent = { req(input$tt_resp, input$tt_group)
        validate(need(length(input$tt_levels) == 2, "Choose two groups to compare."))
        star_ttest(d, "independent", response = input$tt_resp, group = input$tt_group, levels = input$tt_levels,
                   var_equal = identical(input$tt_var, "equal"), alternative = input$tt_alt, alpha = alpha) },
      paired = { req(input$tt_x, input$tt_y)
        validate(need(input$tt_x != input$tt_y, "Choose two different columns for the two measurements."))
        star_ttest(d, "paired", x = input$tt_x, y = input$tt_y, alternative = input$tt_alt, alpha = alpha) },
      one = { req(input$tt_resp)
        validate(need(is.numeric(input$tt_mu) && !is.na(input$tt_mu), "Enter the test value."))
        star_ttest(d, "one", response = input$tt_resp, mu = input$tt_mu, alternative = input$tt_alt, alpha = alpha) }),
      error = function(e) if (inherits(e, "shiny.silent.error") || inherits(e, "validation")) stop(e) else as_error(e))
  }) |> bindEvent(input$go_tt)
  tt_ok <- reactive({ r <- tt_res(); req(!inherits(r, "star_error")); r })
  tt_stale <- stale_flag("go_tt", reactive(list(input$tt_src, input$tt_example, input$tt_file$name, input$tt_type, input$tt_resp, input$tt_group,
                                                input$tt_levels, input$tt_x, input$tt_y, input$tt_mu, input$tt_alt, input$tt_var, input$tt_alpha)))
  output$tt_msg <- renderUI({
    if (!isTRUE(input$go_tt > 0)) return(run_hint("Run t-test"))
    r <- tt_res()
    tagList(if (tt_stale()) stale_note("go_tt"), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })
  tt_tables <- reactive({ r <- tt_ok(); list(desc = tt_desc_display(r), test = tt_test_display(r), normal = tt_normal_display(r), nonpar = tt_nonpar_display(r)) })

  output$tt_results_ui <- renderUI({
    r <- tt_ok(); tb <- tt_tables(); tr <- r$test[r$chosen, ]; k <- tt_digits(r)
    nrm <- r$normality; bad_norm <- nrm$Data[!is.na(nrm$P) & nrm$P < r$alpha]
    small <- min(nrm$N) < 30
    tagList(
      notes_ui(r$data_notes),
      div(class = if (r$significant) "alert alert-success" else "alert alert-info", r$summary),
      key_stats(
        stat("p value", fmt_p(r$p), if (r$significant) paste("significant at", format(r$alpha)) else paste("not significant at", format(r$alpha))),
        stat(switch(r$type, independent = "Difference in means", paired = "Mean difference", one = "Mean - test value"), fmt_n(tr$Difference, k),
             sprintf("%g%% CI %s to %s", 100 * r$conf_level, fmt_n(tr$Lower, k), fmt_n(tr$Upper, k))),
        stat("t statistic", sprintf("%.2f", tr$t), paste("df =", .star_tt_df(tr$DF))),
        stat(if (r$type == "paired") "Cohen's dz" else "Cohen's d", sprintf("%.2f", r$effect_size), .star_tt_effect_word(r$effect_size))),
      result_card("สรุปผล (ภาษาไทย)", p(lang = "th", thai_summary_tt(r)), copy = "cp_tt_th", copy_label = "คัดลอก"),
      result_card("Descriptive statistics", html_table(tb$desc),
        if (r$type == "paired") p(class = "text-muted small mb-0", sprintf("Correlation between the two measurements: r = %.3f.", r$pair_r)),
        copy = "cp_tt_desc", copy_label = "Copy table"),
      result_card("t-test", html_table(tb$test),
        if (r$type == "independent") p(class = "text-muted small mb-0", sprintf("Both versions are shown, as in STAR; the conclusion uses the %s test (change it under Advanced options). Welch's test does not need equal variances and is the safer default.",
                                                                  if (r$var_equal) "pooled (equal variances)" else "Welch")),
        copy = "cp_tt_test", copy_label = "Copy table"),
      result_card("Assumption checks", html_table(tb$normal),
        if (!is.null(r$variance)) p(sprintf("Equality of variances, F test: F(%d, %d) = %.2f, p %s. %s", r$variance$DF1, r$variance$DF2, r$variance$F, .star_fmt_p(r$variance$P),
                                            if (r$variance$P < r$alpha) "The variances differ, so use the Welch test." else "No evidence that the variances differ.")),
        p(class = "text-muted small mb-0",
          if (length(bad_norm) && small) "The data depart from a normal distribution and the sample is small, so the t-test may be unreliable; check the plot for outliers, or use the rank-based (Wilcoxon) test below or a transformation."
          else if (length(bad_norm)) "The data depart somewhat from a normal distribution, but with 30 or more observations per group the t-test is usually still reliable."
          else "The normality tests are only a guide: with few observations they have little power, so also look at the plot.")),
      result_card("Rank-based alternative (nonparametric)", html_table(tb$nonpar),
        div(class = paste("small mb-0", if (length(bad_norm) && small) "alert alert-warning" else "text-muted"),
            "Does not assume a normal distribution. ", if (length(bad_norm) && small) strong("Report this test, because the data are not normal and the sample is small. "),
            "Estimate = Hodges-Lehmann ", if (r$type == "independent") "shift between the groups" else "median difference", "; ",
            "with tied values (or zero differences) the p value and the interval use a normal approximation."),
        copy = "cp_tt_np", copy_label = "Copy table"),
      result_card("APA-style report", p(r$apa), copy = "cp_tt_apa"))
  })
  gg_tt <- reactive(do.call(star_ggplot_ttest, c(list(tt_ok(), main = input$tt_title, xlab = input$tt_xlab, ylab = input$tt_ylab), plot_style("tt"))))
  output$tt_plot <- renderPlot(print(gg_tt()))
  output$dl_tt_plot <- plot_download("tt", gg_tt)
  tt_file_name <- reactive(if (input$tt_src == "up") input$tt_file$name else tt_setup[[input$tt_example]]$file)
  copy_button("cp_tt_th", "สรุปผล", function() thai_summary_tt(tt_ok()))
  output$dl_tt_doc <- downloadHandler("rdstat_ttest_report.doc", function(file) {
    r <- tt_ok(); tb <- tt_tables()
    png <- tryCatch({ f <- tempfile(fileext = ".png"); star_ggsave(gg_tt(), f, width = 6.5, height = 4.5, dpi = 200); f }, error = function(e) NULL)
    blocks <- c(w_p(paste("Data:", tt_file_name() %||% "-", "| Date:", format(Sys.Date()), "|", app_name, version_label()), "small"),
      w_h2("สรุปผล"), w_p(thai_summary_tt(r)), w_p(r$summary),
      w_h2("Descriptive statistics"), word_table(tb$desc),
      w_h2("t-test"), word_table(tb$test),
      w_h2("Assumption checks"), word_table(tb$normal),
      if (!is.null(r$variance)) w_p(sprintf("Equality of variances, F test: F(%d, %d) = %.2f, p %s.", r$variance$DF1, r$variance$DF2, r$variance$F, .star_fmt_p(r$variance$P))),
      w_h2("Rank-based alternative"), word_table(tb$nonpar),
      w_h2("APA-style report"), w_p(r$apa),
      w_h2("Methods and references"), w_p(methods_sentence(gg_version())), paste0("<ul>", paste0("<li>", htmltools::htmlEscape(package_refs()), "</li>", collapse = ""), "</ul>"))
    word_doc(file, paste(app_name, "-", r$method_name), blocks, png)
  })
  output$dl_tt_xlsx <- downloadHandler("rdstat_ttest.xlsx", function(file) {
    r <- tt_ok()
    sheets <- list(Descriptives = r$groups, `t-test` = r$test, Wilcoxon = r$nonparametric, Normality = r$normality)
    if (!is.null(r$variance)) sheets$Variances <- r$variance
    vars <- switch(r$type, independent = sprintf("%s by %s (%s vs %s)", r$response, r$group, r$labels[1], r$labels[2]),
                   paired = paste(r$x, "-", r$y), one = sprintf("%s vs %s", r$response, format(r$mu)))
    sheets$Info <- data.frame(Item = c("App version", "Test", "Variables", "Alternative", "Alpha", "Effect size (Cohen's d)", "Summary", "Data checks"),
                              Value = c(version_label(), r$method_name, vars, r$alternative, r$alpha, round(r$effect_size, 4), r$summary,
                                        if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none"))
    writexl::write_xlsx(sheets, file)
  })
  copy_button("cp_tt_desc", "Descriptive statistics", function() tsv(tt_tables()$desc))
  copy_button("cp_tt_test", "t-test table", function() tsv(tt_tables()$test))
  copy_button("cp_tt_np", "Wilcoxon table", function() tsv(tt_tables()$nonpar))
  copy_button("cp_tt_apa", "APA text", function() tt_ok()$apa)

  # ---- correlation ----
  corr_dat <- use_data("corr", corr_setup)
  output$corr_data_ui <- renderUI(data_preview_ui(corr_dat()))
  output$corr_pickers <- renderUI({
    nm <- numeric_cols(corr_dat()); s <- example_of("corr", corr_setup)
    selectizeInput("corr_vars", "Variables (two or more)", nm, multiple = TRUE, selected = if (!is.null(s)) intersect(s$vars, nm) else head(nm, 6))
  })
  corr_res <- reactive({
    req(input$corr_vars)
    tryCatch(star_correlation(corr_dat(), input$corr_vars, input$corr_method, input$corr_alt, as.numeric(input$corr_alpha), input$corr_adjust), error = as_error)
  }) |> bindEvent(input$go_corr)
  corr_ok <- reactive({ r <- corr_res(); req(!inherits(r, "star_error")); r })
  corr_stale <- stale_flag("go_corr", reactive(list(input$corr_src, input$corr_example, input$corr_file$name, input$corr_vars, input$corr_method,
                                                    input$corr_alt, input$corr_adjust, input$corr_alpha)))
  output$corr_msg <- renderUI({
    if (!isTRUE(input$go_corr > 0)) return(run_hint("Run correlation"))
    r <- corr_res()
    tagList(if (corr_stale()) stale_note("go_corr"), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })
  corr_tables <- reactive({ r <- corr_ok(); list(matrix = corr_matrix_display(r), pairs = corr_pairs_display(r)) })

  output$corr_results_ui <- renderUI({
    r <- corr_ok(); tb <- corr_tables()
    best <- r$pairs[which.max(abs(r$pairs$r)), ]
    tagList(
      notes_ui(r$data_notes),
      div(class = if (any(r$pairs$Significant)) "alert alert-success" else "alert alert-info", r$summary),
      key_stats(
        stat("Significant pairs", sprintf("%d of %d", sum(r$pairs$Significant), nrow(r$pairs)), paste("alpha =", format(r$alpha))),
        stat("Strongest pair", sprintf("%s = %.3f", r$symbol, best$r), paste(best$Variable1, "and", best$Variable2)),
        stat("Method", r$method_name, if (r$adjust != "none") paste(r$adjust, "adjusted p values")),
        stat("Observations per pair", if (min(r$pairs$N) == max(r$pairs$N)) min(r$pairs$N) else paste(min(r$pairs$N), "to", max(r$pairs$N)))),
      result_card("Correlation matrix", html_table(tb$matrix),
        p(class = "text-muted small mb-0", sprintf("%s coefficient. * p < %s, ** p < 0.01, *** p < 0.001%s.", r$method_name, format(r$alpha),
                                                  if (r$adjust != "none") paste0(" (", r$adjust, "-adjusted)") else "")),
        copy = "cp_corr_matrix", copy_label = "Copy table"),
      result_card("All pairs", html_table(tb$pairs), copy = "cp_corr_pairs", copy_label = "Copy table"),
      result_card("APA-style report", lapply(r$apa, p), copy = "cp_corr_apa"))
  })
  output$corr_view_picker <- renderUI({
    v <- corr_ok()$vars
    tagList(selectInput("corr_view", "Plot", c("Scatter plot matrix (all pairs)" = "matrix", "Heatmap of all pairs" = "heat", "Scatter plot of two variables" = "scatter")),
            conditionalPanel("input.corr_view == 'scatter'", fluidRow(
              column(6, selectInput("corr_x", "X axis", v, selected = v[1])),
              column(6, selectInput("corr_y", "Y axis", v, selected = v[2])))))
  })
  gg_corr <- reactive({
    r <- corr_ok(); v <- input$corr_view %||% "matrix"
    x <- input$corr_x; y <- input$corr_y
    pair <- if (v == "scatter" && !is.null(x) && !is.null(y) && x %in% r$vars && y %in% r$vars) {
      validate(need(x != y, "Choose two different variables for the scatter plot."))
      c(x, y)
    }
    do.call(star_ggplot_correlation, c(list(r, pair, main = input$corr_title, xlab = input$corr_xlab, ylab = input$corr_ylab,
                                            type = if (v == "heat") "heatmap" else "matrix"), plot_style("corr")))
  })
  output$corr_plot <- renderPlot(print(gg_corr()))
  output$dl_corr_plot <- plot_download("corr", gg_corr)
  output$dl_corr_xlsx <- downloadHandler("rdstat_correlation.xlsx", function(file) {
    r <- corr_ok(); tb <- corr_tables()
    mat <- function(m) data.frame(Variable = r$vars, m, check.names = FALSE, row.names = NULL)
    writexl::write_xlsx(list(`Correlation (r)` = mat(r$r), `P values` = mat(r$p), N = mat(r$n), Pairs = r$pairs,
                              Info = data.frame(Item = c("App version", "Method", "Alternative", "Alpha", "P adjustment", "Summary", "Data checks"),
                                                Value = c(version_label(), r$method_name, r$alternative, r$alpha, r$adjust, r$summary,
                                                          if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none"))), file)
  })
  copy_button("cp_corr_matrix", "Correlation matrix", function() tsv(corr_tables()$matrix))
  copy_button("cp_corr_pairs", "Pairs table", function() tsv(corr_tables()$pairs))
  copy_button("cp_corr_apa", "APA text", function() paste(corr_ok()$apa, collapse = " "))

  # ---- regression ----
  reg_dat <- use_data("reg", reg_setup)
  output$reg_data_ui <- renderUI(data_preview_ui(reg_dat()))
  output$reg_pickers <- renderUI({
    nm <- numeric_cols(reg_dat()); s <- example_of("reg", reg_setup)
    resp <- if (!is.null(s)) s$resp else tail(nm, 1)
    tagList(selectInput("reg_resp", "Response variable (y)", nm, selected = resp),
            selectizeInput("reg_pred", "Predictor(s) (x): one or more", setdiff(nm, resp), multiple = TRUE,
                           selected = if (!is.null(s)) s$pred else head(setdiff(nm, resp), 1)))
  })
  observeEvent(input$reg_resp, {   # the response cannot also be a predictor
    nm <- numeric_cols(reg_dat()); keep <- setdiff(input$reg_pred, input$reg_resp)
    updateSelectizeInput(session, "reg_pred", choices = setdiff(nm, input$reg_resp), selected = keep)
  }, ignoreInit = TRUE)
  observeEvent(input$reg_example, { s <- reg_setup[[input$reg_example]]; if (!is.null(s)) updateRadioButtons(session, "reg_degree", selected = s$degree) })
  reg_res <- reactive({
    req(input$reg_resp, input$reg_pred)
    tryCatch(star_regression(reg_dat(), input$reg_resp, input$reg_pred, degree = if (length(input$reg_pred) == 1) as.integer(input$reg_degree) else 1L, alpha = as.numeric(input$reg_alpha)), error = as_error)
  }) |> bindEvent(input$go_reg)
  reg_ok <- reactive({ r <- reg_res(); req(!inherits(r, "star_error")); r })
  reg_stale <- stale_flag("go_reg", reactive(list(input$reg_src, input$reg_example, input$reg_file$name, input$reg_resp, input$reg_pred,
                                                  input$reg_degree, input$reg_alpha)))
  output$reg_msg <- renderUI({
    if (!isTRUE(input$go_reg > 0)) return(run_hint("Run regression"))
    r <- reg_res()
    tagList(if (reg_stale()) stale_note("go_reg"), if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message))
  })
  reg_tables <- reactive({ r <- reg_ok(); list(fit = reg_fit_display(r), anova = reg_anova_display(r), coef = reg_coef_display(r)) })

  output$reg_results_ui <- renderUI({
    r <- reg_ok(); tb <- reg_tables()
    tagList(
      notes_ui(r$data_notes),
      div(class = if (r$significant) "alert alert-success" else "alert alert-info", r$summary),
      key_stats(
        stat("R-squared", sprintf("%.3f", r$fit$r2), sprintf("adjusted %.3f", r$fit$adj_r2)),
        stat("Model p value", fmt_p(r$p_model), sprintf("F(%d, %d) = %.2f", r$fit$df1, r$fit$df2, r$fit$f)),
        stat("RMSE", fmt_sig(r$fit$rmse), sprintf("CV = %.1f%%", r$fit$cv)),
        stat("Observations", r$fit$n)),
      result_card("Fitted model", div(class = "equation", r$equation),
        if (!is.null(r$optimum)) p(class = "text-muted small mb-0", sprintf("Stationary point of the curve: %s = %s, fitted %s = %s (a %s%s).", r$predictors, fmt_sig(r$optimum$x), r$response,
                                                                      fmt_sig(r$optimum$y), r$optimum$type, if (r$optimum$inside) "" else "; outside the range of the data"))),
      result_card("Model fit", html_table(tb$fit)),
      result_card("Analysis of variance", html_table(tb$anova), copy = "cp_reg_anova", copy_label = "Copy table"),
      result_card("Parameter estimates", html_table(tb$coef), copy = "cp_reg_coef", copy_label = "Copy table"),
      result_card("APA-style report", p(r$apa), copy = "cp_reg_apa"))
  })
  gg_reg <- reactive(do.call(star_ggplot_regression, c(list(reg_ok(), main = input$reg_title, xlab = input$reg_xlab, ylab = input$reg_ylab), plot_style("reg"))))
  output$reg_plot <- renderPlot(print(gg_reg()))
  output$dl_reg_plot <- plot_download("reg", gg_reg)
  output$reg_diag_ui <- renderUI({
    dg <- reg_ok()$diagnostics
    if (is.null(dg)) return(div(class = "alert alert-warning", "Assumption checks could not be computed for this data."))
    tagList(
      diag_summary_cards(dg),
      div(class = if (dg$ok) "alert alert-success" else "alert alert-warning", tags$ul(lapply(dg$messages, tags$li))),
      if (nrow(dg$outliers)) {
        o <- dg$outliers
        o[] <- lapply(o, function(v) if (is.numeric(v)) fmt_n(v, 3) else as.character(v))
        tagList(h4("Flagged observations"), p(class = "text-muted", "Row = row number in your data. |Studentized residual| > 3 = outlier, 2 to 3 = suspect."), html_table(o))
      })
  })
  output$reg_diag_plot <- renderPlot({ dg <- reg_ok()$diagnostics; req(dg); print(gg_diag(dg, "reg")) })
  reg_predictions <- reactive({
    r <- reg_ok(); req(length(r$predictors) == 1, nzchar(trimws(input$reg_newx %||% "")))
    xs <- star_parse_number(trimws(strsplit(input$reg_newx, "[;,[:space:]]+")[[1]]))
    validate(need(length(xs) > 0 && !anyNA(xs), "Enter numbers separated by commas, for example: 40, 60, 80"))
    star_predict(r, setNames(data.frame(xs), r$predictors))
  })
  output$reg_predict_ui <- renderUI({
    r <- reg_ok()
    if (length(r$predictors) != 1) return(div(class = "alert alert-info", "Prediction is offered for a model with one predictor."))
    tagList(textInput("reg_newx", sprintf("Values of %s (separate with commas)", r$predictors), placeholder = "e.g. 40, 60, 80"),
            tableOutput("reg_pred_tbl"), p(class = "text-muted", "Predicted = fitted mean response; the interval is the confidence interval of that mean. Values outside the range of your data are extrapolations and are marked."))
  })
  output$reg_pred_tbl <- renderTable({
    z <- reg_predictions()
    data.frame(z[[1]], fmt_sig(z$Predicted), fmt_sig(z$Lower), fmt_sig(z$Upper), ifelse(z$Extrapolated, "yes", ""), check.names = FALSE, stringsAsFactors = FALSE) |>
      setNames(c(names(z)[1], "Predicted", "Lower CI", "Upper CI", "Extrapolated"))
  }, align = "r")
  output$dl_reg_xlsx <- downloadHandler("rdstat_regression.xlsx", function(file) {
    r <- reg_ok(); dg <- r$diagnostics
    sheets <- list(Model = data.frame(Item = c("App version", "Response", "Predictor(s)", "Shape", "Equation", "Summary", "Data checks", names(unlist(r$fit))),
                                      Value = c(version_label(), r$response, paste(r$predictors, collapse = ", "), c("line", "quadratic", "cubic")[r$degree], r$equation, r$summary,
                                                if (length(r$data_notes)) paste(r$data_notes, collapse = " | ") else "none", unlist(r$fit))),
                   ANOVA = r$anova, Coefficients = r$coefficients)
    if (!is.null(dg)) sheets$Residuals <- dg$residuals
    writexl::write_xlsx(sheets, file)
  })
  copy_button("cp_reg_anova", "ANOVA table", function() tsv(reg_tables()$anova))
  copy_button("cp_reg_coef", "Parameter estimates", function() tsv(reg_tables()$coef))
  copy_button("cp_reg_apa", "APA text", function() reg_ok()$apa)
}

shinyApp(ui, server)
